<?php
$filters = [];
foreach (['subject','period','status','component','year','semester'] as $key) $filters[$key] = is_string($_GET[$key] ?? null) ? $_GET[$key] : '';
$filtered = array_values(array_filter($activities, fn($a) => (!$filters['year'] || $a['meta']['academic_year'] === $filters['year']) && (!$filters['semester'] || $a['meta']['semester'] === $filters['semester']) && (!$filters['subject'] || (string)$a['classroom']['id'] === $filters['subject']) && (!$filters['period'] || ($a['period'] ?: 'unassigned') === $filters['period']) && (!$filters['status'] || $a['status'] === $filters['status']) && (!$filters['component'] || $a['component'] === $filters['component'])));
$activityPage = page_records($filtered,'page',10);
?>
<section class="glass panel"><form method="get" class="portal-filters"><input type="hidden" name="view" value="activities"><label><span>Subject</span><select name="subject"><option value="">All subjects</option><?php foreach ($classes as $class): ?><option value="<?php echo (int)$class['id']; ?>" <?php echo $filters['subject']===(string)$class['id']?'selected':''; ?>><?php echo esc($class['subject']); ?></option><?php endforeach; ?></select></label><label><span>Term</span><select name="period"><option value="">All terms</option><?php foreach (['prelim'=>'Prelim','midterm'=>'Midterm','finals'=>'Finals','unassigned'=>'Unassigned'] as $id=>$name): ?><option value="<?php echo esc($id); ?>" <?php echo $filters['period']===$id?'selected':''; ?>><?php echo esc($name); ?></option><?php endforeach; ?></select></label><label><span>Component</span><select name="component"><option value="">All components</option><?php foreach (array_unique(array_column($activities,'component')) as $name): ?><option <?php echo $filters['component']===$name?'selected':''; ?>><?php echo esc($name); ?></option><?php endforeach; ?></select></label><label><span>Status</span><select name="status"><option value="">All statuses</option><?php foreach (['Not started','In progress','Submitted','Graded','Awaiting grading','Overdue'] as $name): ?><option <?php echo $filters['status']===$name?'selected':''; ?>><?php echo esc($name); ?></option><?php endforeach; ?></select></label><label><span>Academic year</span><select name="year"><option value="">All years</option><?php foreach(array_unique(array_map(fn($a)=>$a['meta']['academic_year'],$activities)) as $value): ?><option <?php echo $filters['year']===$value?'selected':''; ?>><?php echo esc($value); ?></option><?php endforeach; ?></select></label><label><span>Semester</span><select name="semester"><option value="">All semesters</option><?php foreach(array_unique(array_map(fn($a)=>$a['meta']['semester'],$activities)) as $value): ?><option <?php echo $filters['semester']===$value?'selected':''; ?>><?php echo esc($value); ?></option><?php endforeach; ?></select></label><button class="button button-secondary">Apply</button></form>
<div class="portal-table-scroll"><table class="portal-table"><caption><?php echo count($filtered); ?> activities</caption><thead><tr><th>Activity</th><th>Subject</th><th>Component / term</th><th>Deadline</th><th>Status</th><th>Action</th></tr></thead><tbody><?php foreach ($activityPage['items'] as $activity): ?><tr><th data-label="Activity"><?php echo esc($activity['name']); ?></th><td data-label="Subject"><?php echo esc($activity['classroom']['subject']); ?></td><td data-label="Component"><?php echo esc($activity['component']); ?><small><?php echo esc(ucfirst($activity['period'] ?: 'Unassigned')); ?></small></td><td data-label="Deadline"><?php echo $activity['due'] ? esc(format_date($activity['due'])) : 'No deadline'; ?></td><td data-label="Status"><span class="portal-status <?php echo $activity['status']==='Overdue'?'is-overdue':''; ?>"><?php echo esc($activity['status']); ?></span></td><td><a class="button button-secondary" href="<?php echo esc($activity['url']); ?>">View</a></td></tr><?php endforeach; if (!$filtered): ?><tr><td colspan="6">No activities match these filters.</td></tr><?php endif; ?></tbody></table></div><?php render_pagination($activityPage); ?></section>
